@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + id : int
  + name : string
  + contactInfo : string
}

class Contract {
  + number : int
  + signingDate : date
  + insuredAmount : double
  + policyType : string
}

class Policy {
  + text : string
}

abstract class InsurancePolicy {
  + coverageDetails : string
}

class LifeInsurancePolicy {}
class CarLiabilityPolicy {}
class TheftPolicy {}

class Claim {
  + claimNumber : int
  + dateOfIncident : date
  + description : string
}

class ClaimCase {
  + caseNumber : int
  + status : string
}

class Estimator {
  + id : int
  + name : string
  + expertise : string
}

class CompensationDecision {
  + decisionNumber : int
  + eligibleCosts : double
  + paymentDate : date
}

Customer "1" -- "0..*" Broker
Broker "1" -- "0..*" Contract
Customer "1" -- "0..*" Contract
Contract "1" -- "1" InsurancePolicy
InsurancePolicy "1" ..|> Policy
LifeInsurancePolicy --|> InsurancePolicy
CarLiabilityPolicy --|> InsurancePolicy
TheftPolicy --|> InsurancePolicy
Customer "1" -- "0..*" Claim
Claim "1" -- "0..*" ClaimCase
Estimator "1" -- "0..*" ClaimCase
ClaimCase "1" -- "0..*" CompensationDecision

@enduml

